// features/audit.feature: Audit trails from another tenant are invisible
import { expect, test, uniqueName } from "../../fixtures";

test.describe("vendor audit trail tenant isolation", () => {
  test(
    "audit trails from another tenant are invisible",
    { tag: "@AUD-02" },
    async ({ apiAs }) => {
      // Arrange: a vendor exists in tenant "Globex Procurement"
      const globex = await apiAs("otherTenant");
      const profileResponse = await globex.get("/api/me");
      expect(profileResponse.status()).toBe(200);
      expect((await profileResponse.json()).tenant.name).toBe("Globex Procurement");

      const createResponse = await globex.post("/api/vendors", {
        data: {
          name: uniqueName("Globex Audit Vendor"),
          category: "software",
          contact_email: "vendor-contact@globex.test",
        },
      });
      expect(createResponse.status()).toBe(201);
      const vendorId = ((await createResponse.json()) as { id: string }).id;
      expect(vendorId).toBeTruthy();

      // Sanity check: the vendor's own tenant can see its audit trail
      const ownAudit = await globex.get(`/api/vendors/${vendorId}/audit`);
      expect(ownAudit.status()).toBe(200);

      // Given I am signed in as "member@northwind.test"
      const member = await apiAs("member");

      // Act: request that vendor's audit trail
      const response = await member.get(`/api/vendors/${vendorId}/audit`);

      // Assert
      expect(response.status()).toBe(404);
    },
  );
});
